package ca.mcgill.ecse321.ecse321project03.repository;

import org.springframework.data.repository.CrudRepository;

import ca.mcgill.ecse321.ecse321project03.model.Account;

public interface AccountRepository extends CrudRepository<Account, Integer> {
    
    /**
     * Find an account by username. Auto-generated by Spring Data JPA from method name.
     */
    Account findByUsername(String username);

    /**
     * Find an account by email. Auto-generated by Spring Data JPA from method name.
     */
    Account findByEmail(String email);

    /**
     * Find an account by id.
     */
   // Account findById(int id);
}
